import{_ as t,o as a,c as o,ak as i}from"./chunks/framework.sV-XtlWr.js";const m=JSON.parse('{"title":"Localization","description":"","frontmatter":{"title":"Localization","lang":"en-US"},"headers":[],"relativePath":"operate/localization.md","filePath":"operate/localization.md","lastUpdated":1790080444000}'),n={name:"operate/localization.md"};function r(s,e,d,h,l,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="localization" tabindex="-1">Localization <a class="header-anchor" href="#localization" aria-label="Permalink to &quot;Localization&quot;">​</a></h1><p>Piwi formats every date and time in the browser with the <code>Intl</code> API, so how they read follows a locale (day/month order, 12-hour vs 24-hour time) and which moment they show follows a time zone. Out of the box dates read in US English (<code>9/22/2026, 2:30:05 PM</code>) in the viewer&#39;s own time zone.</p><p>You can change both, at three levels, and each person can keep their own format.</p><h2 id="who-sets-what" tabindex="-1">Who sets what <a class="header-anchor" href="#who-sets-what" aria-label="Permalink to &quot;Who sets what&quot;">​</a></h2><ul><li><strong>Each viewer</strong> picks their own format under <strong>Settings → Localization</strong>. It is saved in that browser and overrides everything below, for that person only.</li><li><strong>An administrator</strong> sets the instance default on the same page. Everyone who has not chosen their own format gets it.</li><li><strong>The environment</strong> can pin the instance default with <code>PIWI_LOCALE</code> and <code>PIWI_TIME_ZONE</code>. Those fields then show read-only in the UI, but a viewer can still override the format for their own browser.</li></ul><p>Precedence, highest first: the per-viewer override, then the env var, then the stored instance default, then the built-in default (<code>en-US</code>, in the viewer&#39;s own browser time zone).</p><h2 id="date-and-time-format" tabindex="-1">Date and time format <a class="header-anchor" href="#date-and-time-format" aria-label="Permalink to &quot;Date and time format&quot;">​</a></h2><p>The format follows a <a href="https://en.wikipedia.org/wiki/IETF_language_tag" target="_blank" rel="noreferrer">BCP-47</a> locale. A few examples of the same instant:</p><table tabindex="0"><thead><tr><th>Locale</th><th>Formatted</th></tr></thead><tbody><tr><td><code>en-US</code></td><td><code>9/22/2026, 2:30:05 PM</code></td></tr><tr><td><code>en-GB</code></td><td><code>22/09/2026, 14:30:05</code></td></tr><tr><td><code>fr-FR</code></td><td><code>22/09/2026 14:30:05</code></td></tr><tr><td><code>de-DE</code></td><td><code>22.09.2026, 14:30:05</code></td></tr><tr><td><code>ja-JP</code></td><td><code>2026/9/22 14:30:05</code></td></tr></tbody></table><p>The settings dropdown lists common locales; <code>Intl</code> accepts any valid tag, so an environment value is not limited to that list. The keyword <code>auto</code> follows each viewer&#39;s browser.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_LOCALE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">fr-FR</span></span></code></pre></div><h2 id="time-zone" tabindex="-1">Time zone <a class="header-anchor" href="#time-zone" aria-label="Permalink to &quot;Time zone&quot;">​</a></h2><p>Absolute times are shown in an <a href="https://en.wikipedia.org/wiki/List_of_tz_database_time_zones" target="_blank" rel="noreferrer">IANA</a> time zone. The default, <code>auto</code>, uses each viewer&#39;s own browser time zone, so a distributed team each reads times in their local clock. Set a fixed zone when everyone should read the same wall-clock time (a shared CI region, for example).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_TIME_ZONE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Europe/Paris</span></span></code></pre></div><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><p><code>PIWI_LOCALE</code> and <code>PIWI_TIME_ZONE</code> are listed with every other setting in the <a href="/reference/configuration.html">configuration reference</a>, and the <a href="/reference/configuration/generator.html">configuration generator</a> can write the block for you.</p>',16)])])}const f=t(n,[["render",r]]);export{m as __pageData,f as default};
